# FDN Voracious Greatshark: "When this creature enters, counter target artifact or creature
# spell."  The compiler's B13-etb+B5a-counter-spell with FDN Essence Scatter's type filter
# widened to artifact or creature.
snap = TriggeredAbility(
    event=ZoneChangeEvent(
        from_zone=Zone(kind=ZoneKind.ANY, controller=ControllerRef.ANY),
        to_zone=Zone(kind=ZoneKind.BATTLEFIELD, controller=ControllerRef.YOU),
        subject=FAtom(pred=FAtomPred.IS_SOURCE),
    ),
    condition=None,
    effect=A(Verb.COUNTER_SPELL, {
        'target': Selector(
            count=QConst(value=1),
            mode=SelectorMode.TARGET,
            filter=FAnd(
                children=(
                    FAtom(pred=FAtomPred.STACK_KIND_EQ, string_value='SPELL'),
                    FOr(
                        children=(
                            FAtom(pred=FAtomPred.TYPE_EQ, string_value='Artifact'),
                            FAtom(pred=FAtomPred.TYPE_EQ, string_value='Creature'),
                        ),
                    ),
                ),
            ),
            zones=(Zone(kind=ZoneKind.STACK, controller=ControllerRef.ANY),),
        ),
    }),
)
abilities = [snap, *compiled]
